// Code node v2: accesso dati tramite $input.first().json
console.log('=== INIZIO ELABORAZIONE ===');

const vectorData = $input.first().json;

console.log('Stato Vector Service:', vectorData.status);
console.log('Uptime:', vectorData.uptime_human);

// Crea la risposta strutturata
const response = {
  technical: {
    status: vectorData.status,
    service: vectorData.service,
    version: vectorData.version,
    uptime: vectorData.uptime_human,
    timestamp: vectorData.timestamp
  },
  demo: {
    title: '✅ INTEGRAZIONE VECTOR-n8n FUNZIONANTE',
    summary: `Il vector-store è ${vectorData.status} e operativo da ${vectorData.uptime_human}`,
    components: {
      embedder: vectorData.services && vectorData.services.embedder ? '✅ OPERATIVO' : '❌ FALLITO',
      vector_store: vectorData.services && vectorData.services.vector_store ? '✅ OPERATIVO' : '❌ FALLITO',
      dlq: vectorData.services && vectorData.services.dlq ? '✅ OPERATIVO' : '❌ FALLITO',
      processor: vectorData.services && vectorData.services.processor ? '✅ OPERATIVO' : '❌ FALLITO'
    },
    check_time: new Date().toISOString(),
    note: 'Questo report è generato da n8n che interroga il Vector Service'
  },
  raw_response: vectorData
};

console.log('=== RISPOSTA CREATA ===');
return [{ json: response }];
